window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"yhbILw63f0w","speaker":"Marie-Edith Tassyla-Ye-Doumbeneny","role":"Foreign Minister","country":"Gabon","region":"Africa","url":"https://www.youtube.com/watch?v=yhbILw63f0w","date":"20260926","title":"🇬🇦 Gabon - Foreign Minister Addresses United Nations General Debate, 81st Session | #UNGA","seconds":606,"words":1223,"counts":{"claims":12,"promises":0,"attacks":0},"topics":[{"topic":"UN theme alignment","share":0.1501,"seconds":91},{"topic":"Morocco","share":0.1187,"seconds":72},{"topic":"Gabon greetings","share":0.1114,"seconds":67},{"topic":"Gabon development plan","share":0.1075,"seconds":65},{"topic":"UN Security Council reform","share":0.1066,"seconds":65},{"topic":"Cuba","share":0.1045,"seconds":63},{"topic":"Gulf of Guinea security","share":0.1013,"seconds":61},{"topic":"Gabon climate finance","share":0.1009,"seconds":61},{"topic":"Digital regulation","share":0.099,"seconds":60}],"timeline":[[2,70,"Gabon greetings"],[71,162,"UN theme alignment"],[163,235,"Morocco"],[236,298,"Gulf of Guinea security"],[299,364,"Gabon development plan"],[366,428,"Gabon climate finance"],[429,489,"Digital regulation"],[492,557,"UN Security Council reform"],[557,620,"Cuba"],[627,630,null]],"stances":{"Gabon greetings":"Marie-Edith Tassyla-Ye-Doumbeneny conveys warm congratulations from the President of Gabon on the election of the General Assembly President.","UN theme alignment":"Gabon fully aligns itself with the session's theme of restoring trust and managing transformation.","Morocco":"Gabon welcomes the adoption of resolution 2797 of 2025 regarding the settlement of the regional dispute over the Moroccan Sahara.","Gulf of Guinea security":"Gabon calls for substantial strengthening of security in the Gulf of Guinea and urgent implementation of UN Security Council Resolution 2719.","Gabon development plan":"The speaker states that Gabon is continuing its social, environmental, and economic transformation under the leadership of President Brice Clotaire Oligui Nguema as outlined in the PNCD for 2026-2030.","Gabon climate finance":"The speaker argues that international financial reforms are necessary to mobilize funding for green development and that Gabon's role as a carbon sink requires fair and sustainable financing.","Digital regulation":"Gabon has introduced temporary and proportionate regulations for digital and AI sectors to protect citizens from risks like privacy infringements and cybercrime due to the lack of an international legal framework.","UN Security Council reform":"Gabon asserts that the UN must reform to include Africa as a permanent member of the Security Council for legitimate global governance.","Cuba":"Gabon reaffirms its support for Cuba and calls for the lifting of sanctions against it."},"claims":[{"t":91,"quote":"the Secretary General of the UN, Antonio Guterres, comes to the end of his second term","topic":"UN theme alignment","kind":"fact"},{"t":131,"quote":"Armed conflicts are becoming more protracted, geopolitical tensions are intensifying, inequalities persist, climate change is accelerating, and humanitarian emergencies are","topic":"UN theme alignment","kind":"fact"},{"t":203,"quote":"Gabon once again welcomes the adoption of resolution 2797 of 2025, which has injected fresh impetus into the settlement of the regional dispute over the Moroccan Sahara based exclusively on the autonomy plan under Moroccan sovereignty.","topic":"Morocco","kind":"fact"},{"t":245,"quote":"This need for inclusiveness is particularly important in the Gulf of Guinea, a maritime area whose importance to international trade is growing by the Consequently","topic":"Gulf of Guinea security","kind":"fact"},{"t":266,"quote":"Mr. President, Gabon, in its capacity as member of the African Union's Peace and Security Council, stresses the urgent need to implement UN Security Council Resolution 2719 on the financing of peacekeeping operations on the Fulfilling this commitment would help consolidate peace in Africa and strengthen cooperation between the UN Security Council and the AU's Peace and Security Council.","topic":"Gulf of Guinea security","kind":"fact"},{"t":299,"quote":"under the leadership of His Excellency Brice Clotaire Oligui Nguema, President of the Republic, Head of State, and Head of Government, Gabon has made dialogue, peace, and respect for its international commitments the guiding principles of its diplomatic action.","topic":"Gabon development plan","kind":"fact"},{"t":329,"quote":"Gabon is continuing its social, environmental, and economic transformation, as set out in our national growth and development plan, the PNCD for 2026-2030.","topic":"Gabon development plan","kind":"fact"},{"t":400,"quote":"green Gabon, a country with extensive forest cover and a low deforestation rate, as well as a major carbon being a major carbon sink","topic":"Gabon climate finance","kind":"fact"},{"t":432,"quote":"digital transformation offers considerable opportunities, it also entails risk, infringements of privacy, disinformation, cybercrime, and the irresponsible use of emerging","topic":"Digital regulation","kind":"fact"},{"t":447,"quote":"The absence of an effective international legal framework leaves the way open for all of these abuses to arise","topic":"Digital regulation","kind":"fact"},{"t":500,"quote":"Gabon therefore welcomes the adoption of UN General Assembly Resolution 80/250 on the African slave trade, characterizing it as the gravest crime against humanity.","topic":"UN Security Council reform","kind":"fact"},{"t":579,"quote":"Gabon here wishes to reaffirm its support for Cuba. Gabon joins the repeated calls by numerous states for the lifting of the","topic":"Cuba","kind":"fact"}],"promises":[],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":2,"topic":"Gabon greetings","text":"I now give the floor to her Excellency Marie Edith Tassila Yanou Moub Obi, Minister of Foreign Affairs and Cooperation in charge of integration and the diaspora of Gabon. &gt;&gt; Monsieur le Président, Mr. President of the General Assembly, Mr. United Nations Secretary General, excellencies, heads of delegation, ladies and gentlemen, President of the General Assembly, allow me to begin by conveying to you the warm congratulations of His Excellency Mr. Brice Clotaire Oligui Nguema, President of the Gabonese Republic, on your outstanding election to preside over this 81st session of the General Assembly."},{"t":71,"topic":"UN theme alignment","text":"I wish to assure you right now of my delegation's full support and express the hope that your term of office will be marked by a spirit of listening and dialogue and by the tireless pursuit of compromise in the service of international peace and cooperation. the Secretary General of the UN, Antonio Guterres, comes to the end of his second term, the President of the Gabonese Republic pays special tribute to him for his steadfast commitment to multilateralism and to upholding the principles enshrined in the United Nations Charter. Ladies and gentlemen, Gabon fully aligns itself with the theme for this session, restoring trust, managing transformation, a United Nations that delivers for all. This theme comes at a pivotal time in international history. Our world is beset by numerous, profound, and interconnected crises. Armed conflicts are becoming more protracted, geopolitical tensions are intensifying, inequalities persist, climate change is accelerating, and humanitarian emergencies are These challenges are compounded by the economic and social consequences of successive crises, food insecurity, the forced displacement of populations, the risks associated with cybercrime, and the upheavals brought about by emerging These"},{"t":163,"topic":"Morocco","text":"realities are are severely testing the international community's ability to act together. In this uncertain environment, there is one value that can still guide us. For Gabon, restoring trust among nations requires more than ever a return to the fundamental principles of international law in general and of the Charter of the United Nations in particular. In this spirit, my country reaffirms its commitment to the principle of non-interference in the domestic affairs of states and to the respect for their sovereignty and territorial integrity. Against this backdrop, Gabon once again welcomes the adoption of resolution 2797 of 2025, which has injected fresh impetus into the settlement of the regional dispute over the Moroccan Sahara based exclusively on the autonomy plan under Moroccan sovereignty. Mr. President, restoring trust depends above all on concrete action that enables us to address together global challenges relating to peace and security, climate change, sustainable development, and pandemics."},{"t":236,"topic":"Gulf of Guinea security","text":"Accordingly, in the face of human tragedies across the world, and particularly in Africa, greater collective engagement is essential. This need for inclusiveness is particularly important in the Gulf of Guinea, a maritime area whose importance to international trade is growing by the Consequently, Gabon calls for a substantial strengthening of security in this area, which represents a foundation for shared Mr. President, Gabon, in its capacity as member of the African Union's Peace and Security Council, stresses the urgent need to implement UN Security Council Resolution 2719 on the financing of peacekeeping operations on the Fulfilling this commitment would help consolidate peace in Africa and strengthen cooperation between the UN Security Council and the AU's Peace and Security Council. Trust also depends on honoring commitments made at the regional level."},{"t":299,"topic":"Gabon development plan","text":"Under the leadership of His Excellency Brice Clotaire Oligui Nguema, President of the Republic, Head of State, and Head of Government, Gabon has made dialogue, peace, and respect for its international commitments the guiding principles of its diplomatic action. Ladies and gentlemen, managing transformation, as the theme of our session calls on us to do, also means knowing how to guide change at the national level. In this regard, under the leadership of the President of the Republic, Gabon is continuing its social, environmental, and economic transformation, as set out in our national growth and development plan, the PNCD for 2026-2030. This development plan also stresses improving the living conditions of our people, particularly through new administrative, hospital, and educational infrastructure in keeping with the sustainable development goals. In light of all of the above, my country calls for a renewed partnership based on mutual respect, shared responsibility, and concrete commitments."},{"t":366,"topic":"Gabon climate finance","text":"Such a partnership must promote the local processing of our natural resources, the diversification of our economy, technology transfer, and the strengthening of national capacities. President, restoring trust also involves reforming the international financial making it more equitable, inclusive, and better tailored to today's challenges. Without this reform, it is becoming almost impossible to mobilize development funding, particularly green Gabon, a country with extensive forest cover and a low deforestation rate, as well as a major carbon being a major carbon sink, therefore calls for [snorts] greater recognition of its contribution to global climate regulation and the ecosystem services that it provides to humanity. These must be properly valued and give rise to fair, [snorts] adequate, predictable, and sustainable financing."},{"t":429,"topic":"Digital regulation","text":"Mr. President, while it's true that digital transformation offers considerable opportunities, it also entails risk, infringements of privacy, disinformation, cybercrime, and the irresponsible use of emerging The absence of an effective international legal framework leaves the way open for all of these abuses to arise, posing a direct threat to the security of our states and the fundamental rights of our citizens. Having already suffered from these various pernicious effects, Gabon has had to introduce [snorts] more appropriate and secure regulation of the digital and artificial intelligence sectors through temporary and proportionate measures motivated solely by the imperative of protecting our citizens. Our aim remains to build an open and secure digital ecosystem that respects freedoms and is fully consistent with our international commitments."},{"t":492,"topic":"UN Security Council reform","text":"Mr. President, if the United Nations is to deliver results for all, it cannot ignore historical debts. Gabon therefore welcomes the adoption of UN General Assembly Resolution 80/250 on the African slave trade, characterizing it as the gravest crime against humanity. An organization that delivers results must also be able to reform itself from The UN must therefore demonstrate its ability to adapt to the international context and effectively address the challenges facing the world. &gt;&gt; This commitment to institutional transformation must take into account the urgent need to reform the Security Indeed, Africa must take its rightful place within the very restricted circle of permanent members. For Gabon, there can be no legitimate global governance without equitable African participation in decisions concerning international peace and Mr."},{"t":557,"topic":"Cuba","text":"President, Gabon's vision is one of inclusive and reformed multilateralism that takes into account the aspirations of peoples, particularly women and young people. It is within this framework that the fundamental right of every state to chart its own course must be guaranteed. pursuant to this principle, Gabon here wishes to reaffirm its support for Cuba. Gabon joins the repeated calls by numerous states for the lifting of the Mr. President, I wish to conclude by saying that Gabon, faithful to its regional and international commitments, and confident in a more peaceful future for all, founded on trust, intends to contribute to building a new global order that is more peaceful, more just, more equitable, and more united. Thank you. &gt;&gt; I thank the Minister of Foreign Affairs and Cooperation in charge of integration and the diaspora of Gabon."},{"t":627,"topic":null,"text":"I now give the floor to Her Excellency Anita Anon,"}],"compare":[{"topic":"UN & its reform","share":0.2567,"mean":0.2045,"rank":63,"others":170},{"topic":"Morocco","share":0.1187,"mean":0.0,"rank":1,"others":0},{"topic":"Cuba","share":0.1045,"mean":0.0109,"rank":7,"others":23},{"topic":"Africa","share":0.1013,"mean":0.023,"rank":18,"others":36},{"topic":"Digital Governance","share":0.099,"mean":0.0029,"rank":2,"others":7}]};
